# Python: dynamisch
x = 42
print(type(x))  # <class 'int'>
x = "jetzt Text"
print(type(x))  # <class 'str'>

// C#: statisch
var n = 42;
n = "Hallo";
// error CS0029: Cannot implicitly
// convert type 'string' to 'int'

var n = 42;        // inferiert: int
Console.WriteLine(n.GetType());
// System.Int32

dynamic d = 5;
d = "jetzt Text";  // erlaubt
Console.WriteLine(d.Length); // 10
// Prüfung erst zur Laufzeit
